const CACHE='danchu-travel-v6-flow-5';
const ASSETS=['./travel-art/travel-props-empty-v5.webp','./scene-surface.js','./travel-art/seoul-clean-v3.webp','./travel-art/seoul-diffuse-v4.webp','./travel-art/seoul-pillow-v3.webp','./travel-art/travel-props-v3.webp','./','./index.html','./style.css','./play.js','./play-engine.js','./world.js','./adventure.js','./manifest.webmanifest','./icon.svg','./travel-art/seoul.webp','./travel-art/tokyo.webp','./travel-art/taipei.webp','./travel-art/bangkok.webp','./travel-art/paris.webp','./travel-art/lisbon.webp','./travel-art/tools.webp','./travel-art/discoveries.webp','./travel-art/seoul-searched.webp','./travel-art/tokyo-searched.webp','./travel-art/taipei-searched.webp','./travel-art/bangkok-searched.webp','./travel-art/paris-searched.webp','./travel-art/lisbon-searched.webp'];
self.addEventListener('install',e=>{e.waitUntil(caches.open(CACHE).then(c=>c.addAll(ASSETS)));self.skipWaiting();});
self.addEventListener('activate',e=>{e.waitUntil(caches.keys().then(keys=>Promise.all(keys.filter(k=>(k.startsWith('strange-cafe-')||k.startsWith('button-')||k.startsWith('danchu-case-')||k.startsWith('danchu-adventure-')||k.startsWith('danchu-travel-'))&&k!==CACHE).map(k=>caches.delete(k)))).then(()=>self.clients.claim()));});
self.addEventListener('fetch',e=>{if(e.request.method!=='GET'||new URL(e.request.url).origin!==self.location.origin)return;e.respondWith(fetch(e.request).then(r=>{if(r.ok){const copy=r.clone();e.waitUntil(caches.open(CACHE).then(c=>c.put(e.request,copy)));}return r;}).catch(()=>caches.match(e.request).then(r=>r||(e.request.mode==='navigate'?caches.match('./index.html'):Response.error()))));});
